// Obsidian Vault 폴더 구조 → Google Drive 폴더 ID 매핑
// 기존 '지식사랑방' 워크플로우와 같은 Google Drive account 사용
//
// ★ 처음 실행 전: Google Drive에 'OpenClaw-Vault' 폴더를 만들고
//   하위에 아래 폴더들을 만든 뒤 ID를 입력하세요.
//   (폴더 URL에서 folders/ 뒤의 문자열이 ID)

const VAULT_DRIVE_ROOT = 'REPLACE_WITH_ROOT_FOLDER_ID';

const FOLDER_MAP = {
  '00-MOC':             'REPLACE_WITH_FOLDER_ID',
  '01-Concepts':        'REPLACE_WITH_FOLDER_ID',
  '02-Entities':        'REPLACE_WITH_FOLDER_ID',
  '03-Notes':           'REPLACE_WITH_FOLDER_ID',
  '04-Daily':           'REPLACE_WITH_FOLDER_ID',
  '05-Weekly':          'REPLACE_WITH_FOLDER_ID',
  '06-Projects':        'REPLACE_WITH_FOLDER_ID',
  '07-Reference':       'REPLACE_WITH_FOLDER_ID',
  'templates':          'REPLACE_WITH_FOLDER_ID'
};

return [{
  json: {
    vaultDriveRoot: VAULT_DRIVE_ROOT,
    folderMap: FOLDER_MAP,
    knowledgePath: '/home/openclaw/.openclaw/workspace/knowledge',
    timestamp: new Date().toISOString()
  }
}];

// 두 방법의 결과를 합치고 중복 제거
const config = $('Vault → Drive 매핑 설정').first().json;
const modifiedFiles = ($('변경된 파일 목록 (SSH)').first().json.stdout || '').split('\n').filter(f => f.trim());
const gitFiles = ($('Git 변경 파일 (SSH)').first().json.stdout || '').split('\n').filter(f => f.trim());

const allFiles = [...new Set([...modifiedFiles, ...gitFiles])].filter(f => f.endsWith('.md'));

if (allFiles.length === 0) {
  return [{ json: { status: 'no_changes', message: '변경된 파일 없음', count: 0 } }];
}

// 각 파일을 개별 아이템으로 반환 (병렬 처리)
return allFiles.map(filePath => {
  // 폴더 매핑: '03-Notes/tech/file.md' → '03-Notes'
  const topFolder = filePath.split('/')[0];
  const targetFolderId = config.folderMap[topFolder] || config.vaultDriveRoot;

  return {
    json: {
      filePath,
      topFolder,
      fileName: filePath.split('/').pop(),
      fullPath: `${config.knowledgePath}/${filePath}`,
      targetFolderId
    }
  };
});

// SSH로 읽은 텍스트를 바이너리(MD 파일)로 변환
const fileData = $('합치기 & 중복제거').item.json;
const content = $input.first().json.stdout || '';
const fileName = fileData.fileName;

const base64Content = Buffer.from(content, 'utf-8').toString('base64');

return {
  json: {
    ...fileData,
    contentLength: content.length
  },
  binary: {
    data: {
      data: base64Content,
      mimeType: 'text/markdown',
      fileName: fileName
    }
  }
};

// 동기화 리포트 생성
const items = $input.all();
const syncedCount = items.length;
const now = new Date().toLocaleString('ko-KR', {timeZone: 'Asia/Seoul'});

const fileList = items.map(item => {
  const name = item.json.fileName || item.json.name || 'unknown';
  const folder = item.json.topFolder || '';
  return `  ${folder}/${name}`;
}).join('\n');

const report = [
  '\ud83d\udcc1 OpenClaw Knowledge Sync',
  '\u2501'.repeat(24),
  `\u23f0 ${now}`,
  `\ud83d\udcc4 ${syncedCount}\uac74 \ub3d9\uae30\ud654 \uc644\ub8cc`,
  '',
  fileList,
  '',
  '\u2705 Google Drive \uc5c5\ub85c\ub4dc \uc644\ub8cc'
].join('\n');

return [{ json: { report, syncedCount, timestamp: now } }];
